<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Noctuary — the field almanac for the night sky</title>
<meta name="description" content="Noctuary plans your observing nights around seeing, transparency, moon phase and your own gear. Stop checking four apps before you haul out the scope.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,300..900;1,9..144,300..900&family=Spline+Sans+Mono:ital,wght@0,300..700;1,300..700&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#0b0d13;
    --ink-2:#10131c;
    --ink-3:#161a26;
    --paper:#ece4d0;
    --paper-dim:rgba(236,228,208,.62);
    --paper-faint:rgba(236,228,208,.34);
    --gold:#d9a441;
    --gold-soft:rgba(217,164,65,.16);
    --sage:#8fb3a4;
    --rust:#c97a58;
    --line:rgba(236,228,208,.16);
    --line-soft:rgba(236,228,208,.08);
    --serif:"Fraunces",Georgia,serif;
    --mono:"Spline Sans Mono",ui-monospace,monospace;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    background:var(--ink);
    color:var(--paper);
    font-family:var(--mono);
    font-size:15px;
    line-height:1.6;
    -webkit-font-smoothing:antialiased;
  }
  ::selection{background:var(--gold);color:var(--ink)}

  .wrap{max-width:1180px;margin:0 auto;padding:0 24px}

  h1,h2,h3,.display{font-family:var(--serif);font-weight:500;letter-spacing:-.01em;line-height:1.08}
  em{font-style:italic}
  a{color:inherit}

  .kicker{
    font-size:11px;letter-spacing:.28em;text-transform:uppercase;
    color:var(--gold);display:flex;align-items:center;gap:12px;
  }
  .kicker::before{content:"";width:34px;height:1px;background:var(--gold);opacity:.7}

  /* ---------- nav ---------- */
  header.site{
    position:sticky;top:0;z-index:50;
    background:rgba(11,13,19,.86);backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line-soft);
  }
  .nav{display:flex;align-items:center;justify-content:space-between;height:64px}
  .logo{display:flex;align-items:center;gap:10px;font-family:var(--serif);font-size:21px;text-decoration:none}
  .logo svg{flex:none}
  .logo b{font-weight:600}
  .logo span{color:var(--gold)}
  .navlinks{display:flex;gap:30px;list-style:none;font-size:12.5px;letter-spacing:.08em;text-transform:uppercase}
  .navlinks a{text-decoration:none;color:var(--paper-dim);transition:color .2s}
  .navlinks a:hover{color:var(--gold)}
  .nav-cta{
    display:inline-block;text-decoration:none;font-size:12.5px;letter-spacing:.1em;text-transform:uppercase;
    border:1px solid var(--gold);color:var(--gold);padding:9px 18px;border-radius:2px;transition:.2s;
  }
  .nav-cta:hover{background:var(--gold);color:var(--ink)}
  .menu-btn{display:none;background:none;border:1px solid var(--line);color:var(--paper);
    font-family:var(--mono);font-size:12px;padding:8px 12px;letter-spacing:.1em;cursor:pointer}

  /* ---------- hero ---------- */
  .hero{position:relative;overflow:hidden;border-bottom:1px solid var(--line-soft)}
  #stars{position:absolute;inset:0;width:100%;height:100%;display:block}
  .hero-inner{
    position:relative;z-index:2;display:grid;grid-template-columns:1.15fr .85fr;
    gap:56px;align-items:center;padding:104px 0 110px;
  }
  .hero h1{font-size:clamp(42px,5.6vw,72px);margin:26px 0 24px;font-weight:400}
  .hero h1 em{color:var(--gold)}
  .hero .lede{max-width:52ch;color:var(--paper-dim);font-size:15.5px}
  .hero-actions{display:flex;gap:16px;margin-top:36px;flex-wrap:wrap}
  .btn{
    display:inline-block;text-decoration:none;padding:14px 26px;border-radius:2px;
    font-size:13px;letter-spacing:.1em;text-transform:uppercase;transition:.2s;
  }
  .btn-solid{background:var(--gold);color:#141008;font-weight:600;border:1px solid var(--gold)}
  .btn-solid:hover{background:#eec06a;border-color:#eec06a}
  .btn-ghost{border:1px solid var(--line);color:var(--paper-dim)}
  .btn-ghost:hover{border-color:var(--gold);color:var(--gold)}
  .hero-meta{margin-top:26px;font-size:12px;color:var(--paper-faint);letter-spacing:.05em}

  /* card: tonight's sky */
  .sky-card{
    background:linear-gradient(175deg,var(--ink-3),var(--ink-2));
    border:1px solid var(--line);border-radius:4px;padding:26px 26px 20px;position:relative;
    box-shadow:0 30px 80px -30px rgba(0,0,0,.8);
  }
  .sky-card::before,.sky-card::after{
    content:"+";position:absolute;color:var(--gold);opacity:.6;font-size:15px;line-height:1;
  }
  .sky-card::before{top:-9px;left:-8px}
  .sky-card::after{bottom:-9px;right:-8px}
  .sc-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;
    border-bottom:1px solid var(--line-soft);padding-bottom:14px;font-size:12px}
  .sc-head .place{letter-spacing:.14em;text-transform:uppercase;color:var(--paper-dim)}
  .sc-head .date{color:var(--gold)}
  .sc-moon{display:flex;gap:18px;align-items:center;padding:18px 0;border-bottom:1px solid var(--line-soft)}
  .sc-moon .moon-txt{font-size:12.5px;color:var(--paper-dim)}
  .sc-moon .moon-txt b{display:block;color:var(--paper);font-size:14px;font-weight:500;letter-spacing:.03em}
  .sc-bars{padding:16px 0;border-bottom:1px solid var(--line-soft)}
  .sc-row{display:grid;grid-template-columns:118px 1fr 44px;align-items:center;gap:12px;
    font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--paper-dim);margin-bottom:11px}
  .sc-row:last-child{margin-bottom:0}
  .bar{height:5px;background:var(--line-soft);border-radius:3px;overflow:hidden}
  .bar i{display:block;height:100%;border-radius:3px;background:var(--sage);
    transform-origin:left;animation:grow 1.3s cubic-bezier(.2,.8,.2,1) both}
  .bar.low i{background:var(--rust)}
  .bar.mid i{background:var(--gold)}
  @keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
  .sc-row .val{text-align:right;color:var(--paper)}
  .targets{list-style:none;padding-top:6px}
  .targets li{display:grid;grid-template-columns:auto 1fr auto auto;gap:14px;align-items:center;
    padding:10px 0;border-bottom:1px dashed var(--line-soft);font-size:13px}
  .targets li:last-child{border-bottom:none}
  .targets .desig{color:var(--gold);font-size:11.5px;min-width:52px}
  .targets .alt,.targets .tr{color:var(--paper-dim);font-size:11.5px}
  .targets .tr{min-width:52px;text-align:right}
  .sc-foot{padding-top:14px;font-size:11px;color:var(--paper-faint);letter-spacing:.06em;text-align:right}
  .pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--sage);margin-right:7px;
    box-shadow:0 0 0 0 rgba(143,179,164,.5);animation:pulse 2.4s infinite}
  @keyframes pulse{0%{box-shadow:0 0 0 0 rgba(143,179,164,.45)}70%{box-shadow:0 0 0 9px rgba(143,179,164,0)}100%{box-shadow:0 0 0 0 rgba(143,179,164,0)}}

  /* ---------- ticker ---------- */
  .ticker{border-bottom:1px solid var(--line-soft);background:var(--ink-2);overflow:hidden}
  .ticker-track{display:flex;gap:64px;white-space:nowrap;padding:14px 0;width:max-content;
    animation:slide 34s linear infinite;font-size:11.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--paper-faint)}
  .ticker-track b{color:var(--paper-dim);font-weight:400}
  .ticker-track .star{color:var(--gold)}
  @keyframes slide{to{transform:translateX(-50%)}}

  /* ---------- section frame ---------- */
  section{padding:110px 0}
  .sec-head{display:flex;justify-content:space-between;align-items:flex-end;gap:32px;
    border-bottom:1px solid var(--line);padding-bottom:34px;margin-bottom:64px}
  .sec-head h2{font-size:clamp(30px,3.6vw,46px);margin-top:18px;font-weight:400;max-width:16ch}
  .sec-head h2 em{color:var(--gold)}
  .sec-head .note{max-width:34ch;color:var(--paper-dim);font-size:13.5px}
  .sec-num{font-family:var(--mono);font-size:11px;letter-spacing:.3em;color:var(--paper-faint)}

  /* ---------- features ---------- */
  .feat-grid{display:grid;grid-template-columns:repeat(6,1fr);border:1px solid var(--line-soft);border-bottom:none;border-right:none}
  .feat{border-bottom:1px solid var(--line-soft);border-right:1px solid var(--line-soft);
    padding:38px 34px 42px;grid-column:span 2;position:relative;transition:background .25s}
  .feat:hover{background:var(--ink-2)}
  .feat.wide{grid-column:span 3}
  .feat .num{font-size:10.5px;letter-spacing:.3em;color:var(--gold);opacity:.85}
  .feat h3{font-size:23px;margin:18px 0 12px;font-weight:500}
  .feat p{color:var(--paper-dim);font-size:13.5px}
  .feat .fig{margin-top:26px}

  /* ---------- ledger / stats ---------- */
  .ledger{background:var(--ink-2);border-top:1px solid var(--line-soft);border-bottom:1px solid var(--line-soft);padding:64px 0}
  .ledger-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
  .stat{padding:8px 26px;border-left:1px solid var(--line-soft)}
  .stat:first-child{border-left:none;padding-left:0}
  .stat .n{font-family:var(--serif);font-size:clamp(34px,4vw,52px);color:var(--gold);font-weight:400;line-height:1}
  .stat .l{font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--paper-dim);margin-top:12px}

  /* ---------- testimonials ---------- */
  .quotes{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
  .quote{border:1px solid var(--line-soft);padding:34px 30px;background:var(--ink-2);position:relative;border-radius:3px}
  .quote::before{content:"“";position:absolute;top:6px;right:20px;font-family:var(--serif);
    font-size:76px;color:var(--gold);opacity:.22;line-height:1}
  .quote .stars{color:var(--gold);letter-spacing:4px;font-size:12px;margin-bottom:16px}
  .quote p{font-size:14px;color:var(--paper);font-family:var(--serif);font-weight:300;font-size:17px;line-height:1.5}
  .quote .who{display:flex;gap:13px;align-items:center;margin-top:26px;padding-top:20px;border-top:1px dashed var(--line-soft)}
  .avatar{width:40px;height:40px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;
    font-size:12.5px;letter-spacing:.05em;border:1px solid var(--gold);color:var(--gold)}
  .who .name{font-size:13px}
  .who .role{font-size:11.5px;color:var(--paper-faint)}

  /* ---------- pricing ---------- */
  .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--line);border-radius:4px;overflow:hidden}
  .plan{padding:42px 34px 46px;border-right:1px solid var(--line);background:var(--ink-2)}
  .plan:last-child{border-right:none}
  .plan.feature{background:linear-gradient(180deg,rgba(217,164,65,.09),rgba(217,164,65,.02));position:relative}
  .plan .tag{position:absolute;top:0;right:0;background:var(--gold);color:var(--ink);font-size:10px;
    letter-spacing:.2em;text-transform:uppercase;padding:6px 14px;font-weight:600}
  .plan h3{font-size:21px;font-weight:500}
  .plan .price{font-family:var(--serif);font-size:46px;color:var(--gold);margin:20px 0 4px;font-weight:400}
  .plan .price small{font-family:var(--mono);font-size:12px;color:var(--paper-faint)}
  .plan .desc{font-size:12.5px;color:var(--paper-dim);min-height:44px;margin-bottom:22px}
  .plan ul{list-style:none;font-size:13px;color:var(--paper-dim);margin-bottom:30px}
  .plan li{padding:9px 0 9px 24px;border-top:1px dashed var(--line-soft);position:relative}
  .plan li::before{content:"✦";position:absolute;left:2px;color:var(--gold);font-size:10px;top:11px}
  .plan .btn{display:block;text-align:center}

  /* ---------- CTA band ---------- */
  .cta-band{border-top:1px solid var(--line-soft);text-align:center;padding:120px 0;position:relative;overflow:hidden}
  .cta-band::before{content:"";position:absolute;inset:0;
    background:radial-gradient(ellipse 60% 70% at 50% 115%,rgba(217,164,65,.14),transparent 65%)}
  .cta-band h2{font-size:clamp(34px,5vw,60px);font-weight:400;max-width:20ch;margin:20px auto 18px;position:relative}
  .cta-band h2 em{color:var(--gold)}
  .cta-band p{color:var(--paper-dim);position:relative}
  .cta-band .btn{margin-top:34px;position:relative}

  /* ---------- footer ---------- */
  footer{border-top:1px solid var(--line);background:var(--ink-2);padding:74px 0 34px}
  .foot-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:44px;margin-bottom:60px}
  footer h4{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:var(--paper-faint);margin-bottom:18px;font-weight:400;font-family:var(--mono)}
  footer ul{list-style:none}
  footer ul li{margin-bottom:11px}
  footer ul a{text-decoration:none;color:var(--paper-dim);font-size:13.5px;transition:color .2s}
  footer ul a:hover{color:var(--gold)}
  .foot-about p{font-size:13px;color:var(--paper-dim);max-width:34ch;margin:16px 0 22px}
  .signup{display:flex;border:1px solid var(--line);border-radius:2px;overflow:hidden;max-width:320px}
  .signup input{flex:1;background:none;border:none;color:var(--paper);padding:11px 14px;font-family:var(--mono);font-size:13px;outline:none}
  .signup input::placeholder{color:var(--paper-faint)}
  .signup button{background:var(--gold);border:none;color:var(--ink);font-family:var(--mono);font-size:11px;
    letter-spacing:.14em;text-transform:uppercase;padding:0 18px;cursor:pointer;font-weight:600}
  .signup button:hover{background:#eec06a}
  .foot-bottom{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;
    border-top:1px solid var(--line-soft);padding-top:26px;font-size:11.5px;color:var(--paper-faint);letter-spacing:.05em}

  /* ---------- responsive ---------- */
  @media (max-width:960px){
    .hero-inner{grid-template-columns:1fr;padding:76px 0 84px;gap:44px}
    .feat-grid{grid-template-columns:1fr 1fr}
    .feat,.feat.wide{grid-column:span 1}
    .quotes{grid-template-columns:1fr}
    .plans{grid-template-columns:1fr}
    .plan{border-right:none;border-bottom:1px solid var(--line)}
    .plan:last-child{border-bottom:none}
    .ledger-grid{grid-template-columns:1fr 1fr;gap:34px 0}
    .stat{padding:0 24px}
    .stat:nth-child(3){border-left:none;padding-left:0}
    .foot-grid{grid-template-columns:1fr 1fr}
  }
  @media (max-width:680px){
    .navlinks,.nav .nav-cta{display:none}
    .menu-btn{display:block}
    header.site.open .navlinks{
      display:flex;position:absolute;top:64px;left:0;right:0;flex-direction:column;gap:0;
      background:var(--ink-2);border-bottom:1px solid var(--line);padding:8px 24px 16px;
    }
    header.site.open .navlinks li{padding:12px 0;border-bottom:1px dashed var(--line-soft)}
    .navlinks a{font-size:14px}
    .feat-grid{grid-template-columns:1fr}
    .ledger-grid{grid-template-columns:1fr 1fr;gap:28px}
    .stat:nth-child(even){border-left:none;padding-left:0}
    .sec-head{flex-direction:column;align-items:flex-start;gap:18px}
    section{padding:78px 0}
    .foot-grid{grid-template-columns:1fr}
    .sc-row{grid-template-columns:96px 1fr 40px}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none!important;transition:none!important}
    html{scroll-behavior:auto}
  }
</style>
</head>
