<!-- ================= HERO ================= -->
<div class="hero" id="top">
  <canvas id="stars" aria-hidden="true"></canvas>
  <div class="wrap hero-inner">
    <div>
      <p class="kicker">Field Almanac · Est. 2021 · Bar Harbor, ME</p>
      <h1>The sky clears on its own schedule. <em>Noctuary</em> knows it.</h1>
      <p class="lede">A planning instrument for amateur astronomers and astrophotographers.
      Noctuary folds seeing, transparency, moonlight and your exact rig into one answer:
      <b>tonight — go, or don't — and what to point at first.</b></p>
      <div class="hero-actions">
        <a class="btn btn-solid" href="#plans">Plan my first night — free</a>
