          <circle cx="62" cy="38" r="6" fill="#d6c89e" opacity=".55"/>
          <circle cx="70" cy="60" r="4" fill="#d6c89e" opacity=".45"/>
          <circle cx="56" cy="72" r="3" fill="#d6c89e" opacity=".4"/>
        </svg>
