        <div class="sc-row"><span>Transparency</span><div class="bar" style="animation-delay:.25s"><i style="width:86%"></i></div><span class="val">High</span></div>
        <div class="sc-row"><span>Cloud cover</span><div class="bar" style="animation-delay:.4s"><i style="width:9%"></i></div><span class="val">9%</span></div>
        <div class="sc-row"><span>Wind · 10 m</span><div class="bar low" style="animation-delay:.55s"><i style="width:58%"></i></div><span class="val">14 mph</span></div>
