  /* ---- starfield ---- */
  var reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var cv=document.getElementById('stars'),ctx=cv.getContext('2d'),stars=[],shoot=null,W,H,dpr;
  function resize(){
    dpr=Math.min(window.devicePixelRatio||1,2);
    W=cv.clientWidth;H=cv.clientHeight;
    cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
    stars=[];var n=Math.round(W*H/6500);
    for(var i=0;i<n;i++){
      stars.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.25+.25,
        p:Math.random()*Math.PI*2,s:.4+Math.random()*1.4,
        c:Math.random()<.12?'217,164,65':(Math.random()<.15?'143,179,164':'236,228,208')});
    }
  }
  function drawStar(st,a){
    ctx.beginPath();ctx.fillStyle='rgba('+st.c+','+a+')';
    ctx.arc(st.x,st.y,st.r,0,6.283);ctx.fill();
  }
  function draw(t){
    ctx.clearRect(0,0,W,H);
    /* faint milky band */
    var g=ctx.createLinearGradient(0,0,W,H);
    g.addColorStop(0,'rgba(236,228,208,0)');
    g.addColorStop(.55,'rgba(180,190,220,.028)');
    g.addColorStop(1,'rgba(236,228,208,0)');
    ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    for(var i=0;i<stars.length;i++){
      var st=stars[i],a=reduced?.7:(.35+.55*Math.abs(Math.sin(st.p+t*.001*st.s)));
      drawStar(st,a);
    }
    /* shooting star */
    if(!reduced){
      if(!shoot&&Math.random()<.0022){
        shoot={x:Math.random()*W*.7+W*.15,y:Math.random()*H*.35,l:0,len:90+Math.random()*90,v:7+Math.random()*4};
      }
      if(shoot){
        shoot.x+=shoot.v;shoot.y+=shoot.v*.45;shoot.l+=shoot.v*1.15;
        if(shoot.l>shoot.len*2.2){shoot=null;}
        else{
          var fade=Math.min(1,shoot.l/40)*Math.max(0,1-shoot.l/(shoot.len*2.2));
          var lg=ctx.createLinearGradient(shoot.x-shoot.len,shoot.y-shoot.len*.45,shoot.x,shoot.y);
          lg.addColorStop(0,'rgba(236,228,208,0)');
          lg.addColorStop(1,'rgba(236,228,208,'+(.85*fade)+')');
          ctx.strokeStyle=lg;ctx.lineWidth=1.3;
          ctx.beginPath();ctx.moveTo(shoot.x-shoot.len,shoot.y-shoot.len*.45);ctx.lineTo(shoot.x,shoot.y);ctx.stroke();
        }
      }
      requestAnimationFrame(draw);
    }
  }
  resize();
  if(reduced){draw(0);}else{requestAnimationFrame(draw);}
  window.addEventListener('resize',function(){resize();if(reduced)draw(0);});
})();
</script>
